import{_ as a,a as r,b as t,c as o,d as i,e as n}from"./chunks/rover_gnss_setup.DjgHd0kP.js";import{_ as s,a as l}from"./chunks/nano_rtk_with_case.Df7ZFmTV.js";import{_ as c,c as h,al as p,o as d}from"./chunks/framework.ByhWQ_D0.js";const R=JSON.parse('{"title":"DATAGNSS NANO HRTK receiver","description":"","frontmatter":{},"headers":[],"relativePath":"zh/gps_compass/rtk_gps_datagnss_nano_hrtk.md","filePath":"zh/gps_compass/rtk_gps_datagnss_nano_hrtk.md"}'),u={name:"zh/gps_compass/rtk_gps_datagnss_nano_hrtk.md"};function m(g,e,f,_,b,k){return d(),h("div",null,e[0]||(e[0]=[p('<h1 id="datagnss-nano-hrtk-receiver" tabindex="-1">DATAGNSS NANO HRTK receiver <a class="header-anchor" href="#datagnss-nano-hrtk-receiver" aria-label="Permalink to &quot;DATAGNSS NANO HRTK receiver&quot;">​</a></h1><p>NANO HRTK receiver is a RTK receiver designed and manufactured by <a href="https://www.datagnss.com/" target="_blank" rel="noreferrer">DATAGNSS</a>.</p><p>It is a high performance dual-band RTK receiver with compass, which is based on CYNOSURE series chipset. It supports global civil navigation systems, including GPS, BDS, GLONASS, Galileo, QZSS, and SBAS.</p><p>NANO HRTK receiver support compass. It is designed for UAV, RTK, and other applications.</p><p><img src="'+a+'" alt="DATAGNSS NANO HRTK Receiver"><img src="'+r+'" alt="DATAGNSS NANO HRTK Antenna"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The NANO HRTK Receiver supports both base and rover options. It does not yet support <em>moving base</em> mode.</p></div><h2 id="购买渠道" tabindex="-1">购买渠道 <a class="header-anchor" href="#购买渠道" aria-label="Permalink to &quot;购买渠道&quot;">​</a></h2><ul><li><a href="https://www.datagnss.com/collections/gnss-for-drone/products/nano-helix-rtk-receiver" target="_blank" rel="noreferrer">NANO HRTK receiver</a> (www.datagnss.com)</li></ul><h2 id="主要特性" tabindex="-1">主要特性 <a class="header-anchor" href="#主要特性" aria-label="Permalink to &quot;主要特性&quot;">​</a></h2><ul><li>Full constellation, multi-frequency GNSS satellite receiver</li><li>Support RTK with up to 10hz output rate</li><li>Standard UART serial interface</li><li>Lightweight and compact size</li></ul><h2 id="frequencies" tabindex="-1">Frequencies <a class="header-anchor" href="#frequencies" aria-label="Permalink to &quot;Frequencies&quot;">​</a></h2><ul><li>GPS/QZSS: L1 C/A, L5C</li><li>GLONASS: L1OF</li><li>BEIDOU: B1I, B2a</li><li>GALILEO: E1, E5a</li><li>IRNSS: L5</li></ul><h2 id="gnss" tabindex="-1">GNSS <a class="header-anchor" href="#gnss" aria-label="Permalink to &quot;GNSS&quot;">​</a></h2><ul><li>128 hardware channels</li><li>3D accuracy: <strong>1.5m</strong> CEP</li><li>RTK accuracy: <strong>2cm</strong> +1PPM(H), 3cm+1PPM(V)</li></ul><h2 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h2><ul><li>UART *2 : 230400bps default</li><li>SMA connector for antenna</li><li>Output rate 5Hz default, up to 10Hz</li><li>Main power supply: 4.7~5.2V</li></ul><h2 id="protocol" tabindex="-1">Protocol <a class="header-anchor" href="#protocol" aria-label="Permalink to &quot;Protocol&quot;">​</a></h2><ul><li>NMEA-0183 output</li><li>RTCM3.x input/output</li></ul><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><ul><li>Operating temp. -20~85°C</li></ul><h2 id="dimension-and-weight" tabindex="-1">Dimension and Weight <a class="header-anchor" href="#dimension-and-weight" aria-label="Permalink to &quot;Dimension and Weight&quot;">​</a></h2><ul><li>35x30mm</li><li>25g</li></ul><h2 id="针脚定义" tabindex="-1">针脚定义 <a class="header-anchor" href="#针脚定义" aria-label="Permalink to &quot;针脚定义&quot;">​</a></h2><p>The board is connected to the autopilot via UART interface.</p><p><img src="'+t+'" alt="NANO HRTK Receiver"></p><p>The 1.25mm pitch 6P connector supports UART for GNSS and I2C for compass.</p><p><img src="'+o+'" alt="PINOUT"></p><h2 id="硬件安装" tabindex="-1">硬件安装 <a class="header-anchor" href="#硬件安装" aria-label="Permalink to &quot;硬件安装&quot;">​</a></h2><p>RTK requires a base RTK module attached to the ground station, and a rover RTK module on the vehicle. The data from the base needs to be transmitted to the drone via telemetry radio and sent to the RTK receiver on the rover.</p><p><img src="'+i+'" alt="RTK setup overview"></p><p>The setup/connections for base and rover modules are shown below.</p><h3 id="base-setup-gcs" tabindex="-1">Base Setup (GCS) <a class="header-anchor" href="#base-setup-gcs" aria-label="Permalink to &quot;Base Setup (GCS)&quot;">​</a></h3><p>The base station connections are shown in the diagram below, along with the connection to a telemetry radio.</p><p><img src="'+s+'" alt="Base module setup"></p><p>Note that for the base we recommend the <a href="https://www.datagnss.com/collections/gnss-for-drone/products/multi-band-rtk-receiver-package" target="_blank" rel="noreferrer">NANO RTK Receiver</a> because it is easier to setup.</p><p><img src="'+l+'" alt="DATAGNSS NANO RTK Receiver with case"></p><p>See to <a href="https://wiki.datagnss.com/index.php/GEM1305-autopilot#Base_station_setup" target="_blank" rel="noreferrer">How to setup Base station</a> for information on how to configure the module for use as a base station (not including step 6 and later, for which you would QGroundControl instead of Mission Planner).</p><h3 id="rover-setup-px4" tabindex="-1">Rover Setup (PX4) <a class="header-anchor" href="#rover-setup-px4" aria-label="Permalink to &quot;Rover Setup (PX4)&quot;">​</a></h3><p>The rover setup showing connections to a GPS port and the (required) connection to a telemetry radio are shown in the diagram below.</p><p><img src="'+n+'" alt="Rover module and Pixhawk big picture connections"></p><p>The diagram below shows the wiring from the <code>GPS2</code> port on the Pixhawk 6c flight controller. Note that an appropriate cable is supplied for this purpose.</p><p>GPS and RTK configuration on PX4 via <em>QGroundControl</em> is plug and play (see <a href="./../gps_compass/rtk_gps.html">RTK GPS</a> for more information).</p><h2 id="package-list" tabindex="-1">Package List <a class="header-anchor" href="#package-list" aria-label="Permalink to &quot;Package List&quot;">​</a></h2><ul><li>NANO HRTK Receiver</li><li>DG-6P-Cxx, GH-1.25mm-GH 6P cable</li><li>Helix antenna L1/L2/L5 (optional)</li></ul><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://wiki.datagnss.com/images/3/31/EVK-DG-1206_V.2.0.pdf" target="_blank" rel="noreferrer">NANO RTK Receiver 2D drawing file</a></li><li><a href="https://docs.datagnss.com/gnss/rtk_receiver/NANO/nano-helix-rtk/" target="_blank" rel="noreferrer">NANO HRTK Receiver Wiki</a> (DATAGNSS WiKi)</li><li><a href="https://docs.datagnss.com/gnss/rtk_receiver/HED-10L/" target="_blank" rel="noreferrer">HED-10L Heading RTK Receiver</a></li></ul><h2 id="more-information" tabindex="-1">More information <a class="header-anchor" href="#more-information" aria-label="Permalink to &quot;More information&quot;">​</a></h2><ul><li><a href="https://docs.datagnss.com/gnss/rtk_receiver/NANO/nano-rtk-receiver" target="_blank" rel="noreferrer">NANO RTK Receiver</a></li><li><a href="https://www.datagnss.com/collections/rtk-antenna/products/smart-helix-antenna" target="_blank" rel="noreferrer">HELIX Antenna for RTK</a></li><li><a href="https://www.datagnss.com/collections/rtk-antenna/products/antenna-agr6302g" target="_blank" rel="noreferrer">RTK Antenna AGR6302G</a></li><li><a href="https://www.datagnss.com/collections/rtk-antenna/products/at400-multi-band-antenna-for-rtk" target="_blank" rel="noreferrer">AT400 RTK Antenna</a></li></ul>',48)]))}const v=c(u,[["render",m]]);export{R as __pageData,v as default};
